def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [[0 for _ in range(w)] for _ in range(h)]
    barrier_rows = {r for r, row in enumerate(grid) if row and all(v == 2 for v in row)}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                out[r][c] = 2
            elif v == 4:
                nr = min(r + 1, h - 1)
                out[nr][c] = 4
                if nr + 1 in barrier_rows:
                    k = 1
                    while nr - k >= 0 or nr - k < h:
                        rr = nr - k
                        if rr < 0:
                            break
                        if 0 <= c - k < w:
                            out[rr][c - k] = 4
                        if 0 <= c + k < w:
                            out[rr][c + k] = 4
                        k += 1
    return out
